#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# run_stall_watchdog.sh <campaign_log> <dest_base> [stall_s=900] [poll_s=60]
# External watchdog for overhead_sweep_v4.sh runs (the real runs have no per-run
# timeout; 2026-09-06 bi3d_freespace lttng #1 hung 3.5 h after "Requesting to
# stop monitoring messages"). Progress signal = timestamp of the last
# r2b.Controller line in the run's launch.log (daemon probe chatter keeps the
# file mtime moving, so mtime is NOT a progress signal). When the benchmark has
# started ("Running benchmark") and no Controller line appeared for stall_s,
# save the container's process table + /dev/shm listing next to the run and
# remove the container BY NAME (docker rm -f) so the sweep continues.
set -u
LOG=$1; DEST=$2; STALL=${3:-900}; POLL=${4:-60}
WLOG=${LOG%.log}_watchdog.log
echo "[watchdog $(date '+%F %T')] start log=$LOG dest=$DEST stall=${STALL}s" >> "$WLOG"
while :; do
    sleep "$POLL"
    line=$(grep -a -- '----- ' "$LOG" | tail -1)          # "[v4 HH:MM:SS] ----- bench [mode #i] FISH=x -----"
    [ -n "$line" ] || continue
    bench=$(echo "$line" | sed -E 's/.*----- ([a-z0-9_]+) \[([a-z]+) #([0-9]+)\].*/\1/')
    mode=$(echo "$line"  | sed -E 's/.*----- ([a-z0-9_]+) \[([a-z]+) #([0-9]+)\].*/\2/')
    idx=$(echo "$line"   | sed -E 's/.*----- ([a-z0-9_]+) \[([a-z]+) #([0-9]+)\].*/\3/')
    cname="ovh-${bench}-${mode}-${idx}"
    docker ps --format '{{.Names}}' | grep -qx "$cname" || continue
    run="$DEST/$bench/${mode}_${idx}"; llog="$run/launch.log"
    [ -f "$llog" ] || continue
    grep -a -q "Running benchmark" "$llog" || continue
    last=$(grep -a -o '\[[0-9]\{10\}\.[0-9]*\] \[r2b\.Controller' "$llog" | tail -1 | grep -o '[0-9]\{10\}')
    [ -n "$last" ] || continue
    now=$(date +%s); idle=$((now - last))
    if [ "$idle" -ge "$STALL" ]; then
        echo "[watchdog $(date '+%F %T')] STALL $cname: no Controller line for ${idle}s — dumping state and removing the container" >> "$WLOG"
        docker exec "$cname" bash -c 'ps -eo pid,ppid,stat,etime,wchan:20,args --sort=etime; echo; ls /dev/shm | wc -l; df -h /dev/shm' > "$run/stall_state.txt" 2>&1
        docker rm -f "$cname" >> "$WLOG" 2>&1
        sleep 120     # let the sweep move to the next run before re-evaluating
    fi
done
